mod credential_enum {
    use serde::{Deserialize, Serialize};

    mod serde_base64_secret {
        use serde::Serializer;

        mod serde_base64 {
            use data_encoding::BASE64;
            use serde::{Deserialize, Serializer};

            pub fn serialize<S: Serializer, B: AsRef<[u8]>>(
                bytes: B,
                serializer: S,
            ) -> Result<S::Ok, S::Error> {
                serializer.serialize_str(&BASE64.encode(bytes.as_ref()))
            }

            pub fn deserialize<'de, D: serde::Deserializer<'de>, B: From<Vec<u8>>>(
                deserializer: D,
            ) -> Result<B, D::Error> {
                let s = String::deserialize(deserializer)?;
                Ok(BASE64
                    .decode(s.as_bytes())
                    .map_err(serde::de::Error::custom)?
                    .into())
            }
        }

        pub fn serialize<S: Serializer>(
            secret: &Vec<u8>,
            serializer: S,
        ) -> Result<S::Ok, S::Error> {
            serde_base64::serialize(secret, serializer)
        }

        pub fn deserialize<'de, D: serde::Deserializer<'de>>(
            deserializer: D,
        ) -> Result<Vec<u8>, D::Error> {
            let inner = serde_base64::deserialize(deserializer)?;
            Ok(inner)
        }
    }

    #[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
    #[serde(tag = "type")]
    pub enum UserAuthCredential {
        #[serde(rename = "password")]
        Password(UserPasswordCredential),
        #[serde(rename = "publickey")]
        PublicKey(UserPublicKeyCredential),
        #[serde(rename = "otp")]
        Totp(UserTotpCredential),
        #[serde(rename = "sso")]
        Sso(UserSsoCredential),
    }

    #[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
    pub struct UserPasswordCredential {
        pub hash: String,
    }
    #[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
    pub struct UserPublicKeyCredential {
        pub key: String,
    }
    #[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
    pub struct UserTotpCredential {
        #[serde(with = "serde_base64_secret")]
        pub key: Vec<u8>,
    }
    #[derive(Debug, Deserialize, Serialize, Clone, PartialEq, Eq)]
    pub struct UserSsoCredential {
        pub provider: Option<String>,
        pub email: String,
    }
}

pub struct Migration;

impl MigrationName for Migration {
    fn name(&self) -> &str {
        "m00009_credential_models"
    }
}

#[async_trait::async_trait]
impl MigrationTrait for Migration {
    async fn up(&self, manager: &SchemaManager) -> Result<(), DbErr> {
        let builder = manager.get_database_backend();
        let db = manager.get_connection();
        let schema = Schema::new(builder);
        manager
            .create_table(schema.create_table_from_entity(otp_credential::Entity))
            .await?;
        manager
            .create_table(schema.create_table_from_entity(password_credential::Entity))
            .await?;
        manager
            .create_table(schema.create_table_from_entity(public_key_credential::Entity))
            .await?;
        manager
            .create_table(schema.create_table_from_entity(sso_credential::Entity))
            .await?;

        let users = User::Entity::find().all(db).await?;
        for user in users {
            #[allow(clippy::unwrap_used)]
            let Ok(credentials) =
                serde_json::from_value::<Vec<UserAuthCredential>>(user.credentials.clone())
            else {
                error!(
                    "Failed to parse credentials for user {}, value was {:?}",
                    user.id, user.credentials
                );
                continue;
            };
            for credential in credentials {
                match credential {
                    UserAuthCredential::Password(password) => {
                        let model = password_credential::ActiveModel {
                            id: Set(Uuid::new_v4()),
                            user_id: Set(user.id),
                            argon_hash: Set(password.hash),
                        };
                        model.insert(db).await?;
                    }
                    UserAuthCredential::PublicKey(key) => {
                        let model = public_key_credential::ActiveModel {
                            id: Set(Uuid::new_v4()),
                            user_id: Set(user.id),
                            openssh_public_key: Set(key.key),
                        };
                        model.insert(db).await?;
                    }
                    UserAuthCredential::Sso(sso) => {
                        let model = sso_credential::ActiveModel {
                            id: Set(Uuid::new_v4()),
                            user_id: Set(user.id),
                            provider: Set(sso.provider),
                            email: Set(sso.email),
                        };
                        model.insert(db).await?;
                    }
                    UserAuthCredential::Totp(totp) => {
                        let model = otp_credential::ActiveModel {
                            id: Set(Uuid::new_v4()),
                            user_id: Set(user.id),
                            secret_key: Set(totp.key),
                        };
                        model.insert(db).await?;
                    }
                }
            }
        }

        manager
            .alter_table(
                Table::alter()
                    .table(User::Entity)
                    .drop_column(User::Column::Credentials)
                    .to_owned(),
            )
            .await?;

        Ok(())
    }

    #[allow(clippy::panic, reason = "dev only")]
    async fn down(&self, _manager: &SchemaManager) -> Result<(), DbErr> {
        panic!("This migration is irreversible");
    }
}

use poem_openapi::param::Path;
use poem_openapi::payload::Json;
use poem_openapi::{ApiResponse, Object, OpenApi};
use sea_orm::{ActiveModelTrait, ColumnTrait, EntityTrait, ModelTrait, QueryFilter, Set};
use uuid::Uuid;
use warpgate_common::{AdminPermission, UserTotpCredential, WarpgateError};
use warpgate_core::logging::{AuditEvent, CredentialChangedVia};
use warpgate_db_entities::{OtpCredential, User};

use super::AdminContext;

#[derive(Object)]
struct ExistingOtpCredential {
    id: Uuid,
}

#[derive(Object)]
struct NewOtpCredential {
    secret_key: Vec<u8>,
}

impl From<OtpCredential::Model> for ExistingOtpCredential {
    fn from(credential: OtpCredential::Model) -> Self {
        Self { id: credential.id }
    }
}

impl From<&NewOtpCredential> for UserTotpCredential {
    fn from(credential: &NewOtpCredential) -> Self {
        Self {
            key: credential.secret_key.clone().into(),
        }
    }
}

#[derive(ApiResponse)]
enum GetOtpCredentialsResponse {
    #[oai(status = 200)]
    Ok(Json<Vec<ExistingOtpCredential>>),
}

#[derive(ApiResponse)]
enum CreateOtpCredentialResponse {
    #[oai(status = 201)]
    Created(Json<ExistingOtpCredential>),
    #[oai(status = 404)]
    NotFound,
}

pub struct ListApi;

#[OpenApi]
impl ListApi {
    #[oai(
        path = "/users/:user_id/credentials/otp",
        method = "get",
        operation_id = "get_otp_credentials"
    )]
    async fn api_get_all(
        &self,
        admin: AdminContext,
        user_id: Path<Uuid>,
    ) -> Result<GetOtpCredentialsResponse, WarpgateError> {
        admin.require(AdminPermission::UsersEdit)?;

        let db = &admin.services().db;

        let objects = OtpCredential::Entity::find()
            .filter(OtpCredential::Column::UserId.eq(*user_id))
            .all(db)
            .await?;

        Ok(GetOtpCredentialsResponse::Ok(Json(
            objects.into_iter().map(Into::into).collect(),
        )))
    }

    #[oai(
        path = "/users/:user_id/credentials/otp",
        method = "post",
        operation_id = "create_otp_credential"
    )]
    async fn api_create(
        &self,
        admin: AdminContext,
        body: Json<NewOtpCredential>,
        user_id: Path<Uuid>,
    ) -> Result<CreateOtpCredentialResponse, WarpgateError> {
        admin.require(AdminPermission::UsersEdit)?;

        let db = &admin.services().db;

        let object = OtpCredential::ActiveModel {
            id: Set(Uuid::new_v4()),
            user_id: Set(*user_id),
            ..OtpCredential::ActiveModel::from(UserTotpCredential::from(&*body))
        }
        .insert(db)
        .await
        .map_err(WarpgateError::from)?;

        let Some(user) = User::Entity::find_by_id(*user_id).one(db).await? else {
            return Ok(CreateOtpCredentialResponse::NotFound);
        };

        AuditEvent::CredentialCreated {
            credential_type: "otp".to_string(),
            credential_name: None,
            via: CredentialChangedVia::Admin,
            user_id: *user_id,
            username: user.username,
            actor_user_id: admin.auth.user_id(),
        }
        .emit();

        Ok(CreateOtpCredentialResponse::Created(Json(object.into())))
    }
}

#[derive(ApiResponse)]
enum DeleteCredentialResponse {
    #[oai(status = 204)]
    Deleted,
    #[oai(status = 404)]
    NotFound,
}

pub struct DetailApi;

#[OpenApi]
impl DetailApi {
    #[oai(
        path = "/users/:user_id/credentials/otp/:id",
        method = "delete",
        operation_id = "delete_otp_credential"
    )]
    async fn api_delete(
        &self,
        admin: AdminContext,
        user_id: Path<Uuid>,
        id: Path<Uuid>,
    ) -> Result<DeleteCredentialResponse, WarpgateError> {
        admin.require(AdminPermission::UsersEdit)?;

        let db = &admin.services().db;

        let Some(role) = OtpCredential::Entity::find_by_id(id.0)
            .filter(OtpCredential::Column::UserId.eq(*user_id))
            .one(db)
            .await?
        else {
            return Ok(DeleteCredentialResponse::NotFound);
        };

        role.delete(db).await?;

        let Some(user) = User::Entity::find_by_id(*user_id).one(db).await? else {
            return Ok(DeleteCredentialResponse::NotFound);
        };

        AuditEvent::CredentialDeleted {
            credential_type: "otp".to_string(),
            credential_name: None,
            via: CredentialChangedVia::Admin,
            user_id: *user_id,
            username: user.username,
            actor_user_id: admin.auth.user_id(),
        }
        .emit();

        Ok(DeleteCredentialResponse::Deleted)
    }
}

use poem::Request;
use poem_openapi::SecurityScheme;
use poem_openapi::auth::ApiKey;
use warpgate_common_http::AuthenticatedRequestContext;

#[allow(clippy::unused_async)]
async fn authenticated_context(req: &Request, _key: ApiKey) -> Option<AuthenticatedRequestContext> {
    req.data::<AuthenticatedRequestContext>().cloned()
}

#[derive(SecurityScheme)]
#[oai(
    rename = "TokenSecurityScheme",
    ty = "api_key",
    key_name = "X-Warpgate-Token",
    key_in = "header",
    checker = "authenticated_context"
)]
pub struct TokenAuth(AuthenticatedRequestContext);

#[derive(SecurityScheme)]
#[oai(
    rename = "CookieSecurityScheme",
    ty = "api_key",
    key_name = "warpgate-http-session",
    key_in = "cookie",
    checker = "authenticated_context"
)]
pub struct CookieAuth(AuthenticatedRequestContext);

/// Requests forwarded by a cluster peer authenticate with the cluster token
/// (plus the forwarded user identity resolved into the request authorization —
/// see `cluster_request_authorization`). The checker only reads the context
/// that `inject_request_authorization` attaches after verifying the token, so
/// a bogus header value alone never authenticates.
#[derive(SecurityScheme)]
#[oai(
    rename = "ClusterSecurityScheme",
    ty = "api_key",
    key_name = "x-warpgate-cluster-token",
    key_in = "header",
    checker = "authenticated_context"
)]
pub struct ClusterAuth(AuthenticatedRequestContext);

/// Auth gate - both a check and a AuthenticatedRequestContext extractor at once
#[derive(SecurityScheme)]
pub enum AuthedSession {
    Token(TokenAuth),
    Cookie(CookieAuth),
    Cluster(ClusterAuth),
}

impl AuthedSession {
    pub const fn ctx(&self) -> &AuthenticatedRequestContext {
        match self {
            Self::Token(t) => &t.0,
            Self::Cookie(c) => &c.0,
            Self::Cluster(c) => &c.0,
        }
    }
}

impl std::ops::Deref for AuthedSession {
    type Target = AuthenticatedRequestContext;

    fn deref(&self) -> &Self::Target {
        self.ctx()
    }
}

#[cfg(test)]
mod tests {
    use poem::test::TestClient;
    use poem_openapi::payload::PlainText;
    use poem_openapi::{OpenApi, OpenApiService};

    use super::AuthedSession;

    struct TestApi;

    #[OpenApi]
    impl TestApi {
        #[oai(path = "/guarded", method = "get")]
        async fn guarded(&self, _auth: AuthedSession) -> PlainText<String> {
            PlainText("reached".into())
        }
    }

    // The authenticated context is present as request data only when authenticated
    // (see `inject_request_authorization`). Without it, the gate must reject — whether or
    // not a session cookie happens to be present. The accept path needs a real `Services`
    // and is covered by the e2e suite.
    fn client() -> TestClient<impl poem::Endpoint> {
        TestClient::new(OpenApiService::new(TestApi, "test", "1.0"))
    }

    #[tokio::test]
    async fn rejects_unauthenticated_request_with_session_cookie() {
        let resp = client()
            .get("/guarded")
            .header("cookie", "warpgate-http-session=anything")
            .send()
            .await;
        resp.assert_status(http::StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn rejects_request_with_no_credentials() {
        let resp = client().get("/guarded").send().await;
        resp.assert_status(http::StatusCode::UNAUTHORIZED);
    }

    #[tokio::test]
    async fn rejects_unverified_cluster_token_header() {
        let resp = client()
            .get("/guarded")
            .header("x-warpgate-cluster-token", "anything")
            .send()
            .await;
        resp.assert_status(http::StatusCode::UNAUTHORIZED);
    }
}

