fn certificate_fingerprint(certificate_pem: &str) -> Result<String, WarpgateError> {
    Ok(warpgate_ca::certificate_sha256_hex_fingerprint(
        &warpgate_ca::deserialize_certificate(certificate_pem)?,
    )?)
}

